#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 数组要开得比题目上限大一点：n 最多 100，开 105 就够用。
    // 合法下标只有 0 ~ n-1，写成 a[n] 就是越界。
    int a[105];

    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    // 倒着走：从 a[n-1] 一直输出到 a[0]。
    // i 用 int（不要用 unsigned），条件必须写 i >= 0，
    // 写成 i > 0 会漏掉第一个数。
    for (int i = n - 1; i >= 0; i--) {
        if (i != n - 1) {
            cout << " ";   // 只在两个数之间加空格，行首不加
        }
        cout << a[i];
    }
    cout << endl;
    return 0;
}

