#include <iostream>
#include <iomanip>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    // C++ 里更常用 vector：长度跟着 n 走，不用像数组那样先猜一个上限。
    vector<int> a;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        a.push_back(x);   // 塞到末尾，a.size() 自动加一
    }

    int sum = 0;          // 求和的初值必须是 0，不能是随机值
    // 范围 for：把 a 里的每个元素依次取出来叫 x
    for (int x : a) {
        sum += x;
    }

    // 关键：sum 和 n 都是 int，sum / n 会做整数除法把小数丢掉。
    // 乘 1.0（或者写 (double)sum）才会按小数算。
    double avg = sum * 1.0 / n;

    cout << sum << endl;
    cout << fixed << setprecision(2) << avg << endl;
    return 0;
}

