#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int a[105];
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    // 初值来自数据本身（第一个元素），不要凭空写 0：
    // 如果所有数都是负数，maxVal = 0 会让最大值变成一个没出现过的 0。
    int maxVal = a[0], maxPos = 1;
    int minVal = a[0], minPos = 1;

    // 从第 2 个元素（下标 1）开始比
    for (int i = 1; i < n; i++) {
        // 严格大于才更新 —— 同一个最大值出现多次时，保留的是第一次的位置
        if (a[i] > maxVal) {
            maxVal = a[i];
            maxPos = i + 1;   // 下标从 0 开始，位置从 1 开始，所以要 +1
        }
        if (a[i] < minVal) {
            minVal = a[i];
            minPos = i + 1;
        }
    }

    cout << maxVal << endl;
    cout << maxPos << endl;
    cout << minVal << endl;
    cout << minPos << endl;
    return 0;
}

