#include <iostream>
#include <string>
using namespace std;

int main() {
    // cin >> s 读的是「一个单词」：跳过开头的空白，遇到空格或换行就停。
    // 所以题目说单词不含空格 —— 要读一整句话得用 getline（下一题会讲）。
    string s;
    cin >> s;

    cout << s.length() << endl;

    // 下标和数组一样从 0 开始，最后一个字符是 s[s.length() - 1]。
    // 别写成 s[s.length()] —— 那是长度，正好越界。
    cout << s[0] << " " << s[s.length() - 1] << endl;

    // string 可以直接用 + 拼接，结果是新字符串，原来的 s 不变
    string t = s + s;
    cout << t << endl;
    return 0;
}

