#include <iostream>
#include <string>
using namespace std;

int main() {
    // getline 读「一整行」：一直读到换行符为止，空格不再算结束。
    // 它会跳过开头的空白吗？不会 —— 行首的空格会原样读进来（和 cin >> 不一样）。
    // 结尾的 '\n' 被丢掉，不会进 line。
    string line;
    getline(cin, line);

    cout << line.length() << endl;

    int spaces = 0;
    string out;   // 空字符串，后面一个字符一个字符往里加

    // length() 返回的是无符号类型，转成 int 再比较，省得编译器警告
    for (int i = 0; i < (int)line.length(); i++) {
        if (line[i] == ' ') {
            spaces++;
            out += '-';        // string 支持 += 追加
        } else {
            out += line[i];
        }
    }

    cout << spaces << endl;
    cout << out << endl;
    return 0;
}

