#include <iostream>
using namespace std;

int main() {
    int r, c;
    cin >> r >> c;

    // 二维数组 a[i][j]：第一个下标是「行」，第二个是「列」。
    // 顺序写反了照样能编译、照样能跑，只是答案全错 —— 这是二维数组最常见的坑。
    // 行列上限都是 50，各开 55 留点余量。
    int a[55][55];

    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            cin >> a[i][j];
        }
    }

    // 转置输出：外层走「列」，内层走「行」。
    // 一共输出 c 行，每行 r 个数（行列数正好和输入反过来）。
    for (int j = 0; j < c; j++) {
        for (int i = 0; i < r; i++) {
            if (i > 0) {
                cout << " ";   // 每个数之间一个空格，行首不加
            }
            cout << a[i][j];
        }
        cout << endl;
    }
    return 0;
}

